for r,pp in zip(rows,p): d[(r['number_set'],int(r['target']))].append((int(r['rating']),pp))
def inc(e):
  return len(e)>1 and len({x%2 for x in e})>1 and not all(x%5==0 for x in e) and len({x%10 for x in e})>1
out=[]
for (s,t),v in d.items():
  e=[int(x) for x in s.split(',')]
  if inc(e):
    m=np.mean([a for a,_ in v]); q=v[0][1]; out.append((s,t,round(m,2),round(q,2)))
print(len(out))
for o in sorted(out,key=lambda o:-(o[2]-o[3])**2)[:40]: print(o)
"

